import React,{useState,FormEvent} from 'react';
import {Navigate} from 'react-router-dom';
import {useAuth} from '../Auth';
import {login,loginGoogle} from '../store';
import {User} from '../types';
import {Btn} from '../components/ui';
const inp="w-full rounded-lg bg-primary-50 pl-10 pr-10 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-500";
export default function Login(){
  const {user,signIn}=useAuth();
  const [email,setE]=useState('');const [pw,setP]=useState('');const [show,setS]=useState(false);const [err,setErr]=useState('');const [busy,setB]=useState(false);
  if(user)return <Navigate to="/modules" replace/>;
  const run=async(f:()=>Promise<User>)=>{setB(true);setErr('');try{signIn(await f())}catch(e){setErr((e as Error).message);setB(false)}};
  const submit=(e:FormEvent)=>{e.preventDefault();run(()=>login(email,pw))};
  return <div className="min-h-screen flex flex-col lg:flex-row bg-primary-900">
    <section className="relative h-64 sm:h-72 lg:h-auto lg:flex-1 bg-cover bg-center" style={{backgroundImage:"url('/images/gedung.jpeg')"}}>
      <div className="absolute inset-0 bg-gradient-to-t from-primary-900/85 to-primary-900/30"/>
      <div className="relative h-full flex flex-col justify-end lg:justify-center p-6 sm:p-10 lg:p-16 pb-14 lg:pb-16 text-white">
        <p className="text-xl sm:text-3xl xl:text-5xl font-light leading-tight">Sistem Informasi<br/>Kerja Praktek &amp; Tugas Akhir</p>
        <p className="mt-2 font-bold uppercase text-sm sm:text-lg xl:text-2xl">Teknik Informatika<br/>Universitas Widyatama</p></div></section>
    <section className="relative -mt-8 lg:mt-0 rounded-t-[2rem] lg:rounded-none bg-white lg:w-[30rem] xl:w-[34rem] flex flex-col justify-center px-6 sm:px-12 py-8 flex-1 lg:flex-none">
      <div className="flex justify-center items-center gap-6"><img src="/images/logowidit.jpg" alt="Logo Widyatama" className="h-14 sm:h-16 object-contain"/><img src="/images/logoif.jpg" alt="Logo IF" className="h-14 sm:h-16 object-contain"/></div>
      <h2 className="mt-6 text-lg font-bold">Masuk ke Akun</h2>
      <button disabled={busy} onClick={()=>run(()=>loginGoogle(window.prompt('Masukkan email akun Google Anda:')||''))}
        className="mt-4 w-full flex items-center justify-center gap-2 rounded-lg border border-slate-200 bg-slate-50 py-2.5 text-sm font-semibold hover:bg-slate-100 disabled:opacity-50">
        <b className="text-primary-600">G</b> Google</button>
      <div className="my-4 flex items-center gap-3 text-xs text-slate-400"><hr className="flex-1"/>atau lanjutkan dengan<hr className="flex-1"/></div>
      <form onSubmit={submit} className="space-y-4">
        <label className="block text-sm font-medium">Email / Akun Pengguna<span className="text-red-500">*</span>
          <div className="relative mt-1"><span className="absolute left-3 top-2.5 text-primary-500">👤</span>
          <input className={inp} required type="email" placeholder="Masukkan email/NPM/NIP/username yang terdaftar" value={email} onChange={e=>setE(e.target.value)}/></div></label>
        <label className="block text-sm font-medium">Password<span className="text-red-500">*</span>
          <div className="relative mt-1"><span className="absolute left-3 top-2.5 text-primary-500">🔒</span>
          <input className={inp} required type={show?'text':'password'} placeholder="Masukkan password" value={pw} onChange={e=>setP(e.target.value)}/>
          <button type="button" aria-label="Tampilkan password" className="absolute right-3 top-2.5" onClick={()=>setS(!show)}>{show?'🙈':'👁'}</button></div></label>
        <button type="button" className="block ml-auto text-xs text-primary-700 underline" onClick={()=>alert('Lupa kata sandi: Coming Soon')}>Lupa Kata Sandi?</button>
        {err&&<p className="text-sm text-red-600">{err}</p>}
        <Btn v="primary" type="submit" disabled={busy} className="w-full py-3">{busy?'Memproses...':'Masuk'}</Btn></form>
      <p className="mt-8 text-center text-xs text-slate-400">© Made with love in Informatika</p>
    </section></div>}
